#!/usr/bin/env bash
# step48 — Country restrictions (#2): per-product geo_note. Admin editor field,
# saved on create/update, shown as an availability note on the product page.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step48-$TS
mkdir -p "$BAK"
echo "==> backup -> $BAK"
for f in routes/adminCatalog.js routes/products.js views/admin/product_edit.ejs views/product.ejs; do
  mkdir -p "$BAK/$(dirname "$f")"; cp "$APP/$f" "$BAK/$f"
done
restore(){ echo "!! rollback"; for f in routes/adminCatalog.js routes/products.js views/admin/product_edit.ejs views/product.ejs; do cp "$BAK/$f" "$APP/$f"; done; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR

echo "==> migration: products.geo_note"
( sudo -u postgres psql -d gsz -c "ALTER TABLE products ADD COLUMN IF NOT EXISTS geo_note text;" 2>&1 \
  || psql -U gsz_user -d gsz -c "ALTER TABLE products ADD COLUMN IF NOT EXISTS geo_note text;" 2>&1 ) | tail -1

writef(){ local dest="$APP/$1" b64="$2" md5="$3"; base64 -d "$b64" > "$dest"; local got; got=$(md5sum "$dest"|awk '{print $1}'); echo "   $1 $got $([ "$got" = "$md5" ] && echo OK || echo MISMATCH)"; [ "$got" = "$md5" ] || { echo "!! md5 mismatch $1"; false; }; }
cat > /tmp/s48_acat.b64 <<'B48_acat'

B48_acat
writef "routes/adminCatalog.js" /tmp/s48_acat.b64 "1220cd276ada780a9a16a5e16cd9d2ab"
rm -f /tmp/s48_acat.b64
cat > /tmp/s48_prod.b64 <<'B48_prod'

B48_prod
writef "routes/products.js" /tmp/s48_prod.b64 "8057fe375cebec978d3b4077653fedf3"
rm -f /tmp/s48_prod.b64
cat > /tmp/s48_pedit.b64 <<'B48_pedit'

B48_pedit
writef "views/admin/product_edit.ejs" /tmp/s48_pedit.b64 "e7668e3cef3804ea88432aaa7d60b646"
rm -f /tmp/s48_pedit.b64
cat > /tmp/s48_pview.b64 <<'B48_pview'

B48_pview
writef "views/product.ejs" /tmp/s48_pview.b64 "6ed6d28e52646d3ec6523aebeca64513"
rm -f /tmp/s48_pview.b64

echo "==> node --check"
node --check "$APP/routes/adminCatalog.js"
node --check "$APP/routes/products.js"
echo "==> ejs compile"
node -e 'const ejs=require("/opt/gsz/node_modules/ejs"),fs=require("fs");["views/admin/product_edit.ejs","views/product.ejs"].forEach(function(f){ejs.compile(fs.readFileSync("/opt/gsz/"+f,"utf8"),{filename:"/opt/gsz/"+f});console.log("   compiled "+f);});'
echo "==> verify geo_note wired"
grep -q 'p.geo_note' "$APP/routes/products.js" || { echo "!! products.js missing geo_note select"; false; }
grep -q 'name="geo_note"' "$APP/views/admin/product_edit.ejs" || { echo "!! editor field missing"; false; }

echo "==> pm2 restart gsz"; pm2 restart gsz --update-env >/dev/null; sleep 3
H=$(curl -s -m 15 http://127.0.0.1:3900/ || true)
grep -q '</html>' <<<"$H" || { echo "!! home broken"; false; }
SLUG=$(grep -oE '/product/[a-z0-9-]+' <<<"$H" | head -1 | sed 's#/product/##')
[ -n "$SLUG" ] || { echo "!! no slug"; false; }
PP=$(curl -s -m 15 "http://127.0.0.1:3900/product/$SLUG" || true)
grep -q '</html>' <<<"$PP" || { echo "!! product page broken"; false; }
grep -q 'Add to cart' <<<"$PP" || { echo "!! product page missing content"; false; }
if grep -qi 'Product error:' <<<"$PP"; then echo "!! product route threw"; false; fi

trap - ERR
echo "==> step48 OK — country-restriction note wired. Set it per product in Admin → Products → Edit. Backup: $BAK"
